/**
 * Usage analytics (Feature 13) — `GET /admin/analytics`.
 *
 * LIVE (today, backend aggregates): passengers per route, occupancy by bus, trips today,
 * average delay, QR boardings by time slot.
 * SYNTHETIC (no history is stored yet): deterministic demo series generated by the
 * backend from SEED + service date, shown in a separate block labelled
 * "Synthetic demo data". Nothing here is random or computed from scratch in the browser.
 */
import type { ReactNode } from "react";

import type { AdminAnalytics, LabelValue } from "../api/client";
import { CROWDING_TONE } from "../labels";

interface Bar {
  label: string;
  value: number;
  swatch?: string | null;
  tone?: string;
  text?: string;
}

/** Horizontal bars as a real table (so the chart is also its own table view). */
function BarChart({
  title,
  bars,
  unit = "",
  max,
  synthetic = false,
  empty = "No data yet.",
  children,
}: {
  title: string;
  bars: Bar[];
  unit?: string;
  max?: number;
  synthetic?: boolean;
  empty?: string;
  /** Headline shown above the bars (e.g. a hero number). */
  children?: ReactNode;
}) {
  const top = max ?? Math.max(1, ...bars.map((b) => b.value));
  return (
    <figure className={`chart${synthetic ? " is-synthetic" : ""}`} aria-label={title}>
      <figcaption>{title}</figcaption>
      {children}
      {bars.length === 0 ? (
        <p className="empty small">{empty}</p>
      ) : (
        <table className="bars">
          <tbody>
            {bars.map((b) => (
              <tr key={b.label} title={`${b.label}: ${b.text ?? `${b.value}${unit}`}`}>
                <th scope="row">
                  {b.swatch && (
                    <span className="swatch" style={{ background: b.swatch }} aria-hidden="true" />
                  )}
                  {b.label}
                </th>
                <td>
                  <span className="bar-track">
                    <span
                      className={`bar${b.tone ? ` crowd-${b.tone}` : ""}`}
                      style={{ width: `${Math.max(0, Math.min(100, (100 * b.value) / top))}%` }}
                    />
                  </span>
                </td>
                <td className="num">{b.text ?? `${b.value}${unit}`}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </figure>
  );
}

const fromLV = (xs: LabelValue[], swatch = false): Bar[] =>
  xs.map((x) => ({ label: x.label, value: x.value, swatch: swatch ? x.color : null }));

export function AnalyticsPanel({
  analytics,
  error,
}: {
  analytics: AdminAnalytics | null;
  error: string | null;
}) {
  if (!analytics) {
    return (
      <section className="panel" aria-label="Analytics" id="analytics">
        <header className="panel-head">
          <h2>Usage analytics</h2>
        </header>
        {error ? (
          <p className="error" role="alert">
            {error}
          </p>
        ) : (
          <p className="muted">Loading analytics…</p>
        )}
      </section>
    );
  }
  const { live, synthetic } = analytics;
  const peak = synthetic.peak_boarding_by_hour.reduce<LabelValue | null>(
    (best, x) => (best === null || x.value > best.value ? x : best),
    null,
  );
  const avg = live.average_delay.fleet_avg_delay_min;
  return (
    <section className="panel" aria-label="Analytics" id="analytics">
      <header className="panel-head">
        <h2>Usage analytics</h2>
        {error && (
          <span className="error small" role="alert">
            {error}
          </span>
        )}
      </header>

      <div className="analytics-block" aria-label="Live analytics">
        <h3>
          Today · live <span className="live-tag">Live</span>
        </h3>
        <div className="charts">
          <BarChart
            title="Passengers per route"
            bars={fromLV(live.passengers_per_route, true)}
            empty="No trips have departed yet."
          />
          <BarChart
            title="Occupancy by bus"
            max={100}
            unit="%"
            bars={live.occupancy_by_bus.map((b) => ({
              label: `Bus ${b.bus_id.replace(/^B/, "")}`,
              value: b.occupancy_percentage ?? 0,
              tone: CROWDING_TONE[b.crowding],
              text: `${b.occupancy}/${b.capacity} · ${b.occupancy_percentage ?? "—"}%`,
            }))}
            empty="No bus is on a trip."
          />
          <BarChart title="Trips today" bars={fromLV(live.trips_by_departure_hour)}>
            <dl className="mini-stats">
              <div>
                <dt>Total</dt>
                <dd>{live.trips_today.total}</dd>
              </div>
              <div>
                <dt>Active</dt>
                <dd>{live.trips_today.active}</dd>
              </div>
              <div>
                <dt>Completed</dt>
                <dd>{live.trips_today.completed}</dd>
              </div>
              <div>
                <dt>Scheduled</dt>
                <dd>{live.trips_today.scheduled}</dd>
              </div>
            </dl>
            <p className="muted small">Departures per hour</p>
          </BarChart>
          <BarChart
            title="Average delay"
            unit=" min"
            bars={fromLV(live.average_delay.by_route, true)}
            empty="No bus is running."
          >
            <p className="hero">
              {avg === null ? "—" : `${avg > 0 ? "+" : ""}${avg} min`}
              <span className="muted small">
                {" "}
                · fleet average of {live.average_delay.buses_measured} running buses
              </span>
            </p>
          </BarChart>
          <BarChart
            title="QR boardings by time (today)"
            bars={fromLV(live.qr_boardings_by_slot)}
            empty="No QR boardings yet today."
          />
        </div>
      </div>

      <div className="analytics-block synthetic" aria-label="Synthetic analytics">
        <h3>
          History <span className="sim-tag">{synthetic.label}</span>
        </h3>
        <p className="footnote">
          No trip history is stored yet, so these charts use generated demo data (seed{" "}
          {synthetic.seed}) — not real observations.
        </p>
        <div className="charts">
          <BarChart
            synthetic
            title="Passengers per day (last 7 days)"
            bars={fromLV(synthetic.daily_passengers)}
          />
          <BarChart
            synthetic
            title="Average delay per day"
            unit=" min"
            bars={fromLV(synthetic.average_delay_by_day)}
          />
          <BarChart
            synthetic
            title={`Peak boarding time${peak ? ` — ${peak.label}` : ""}`}
            bars={fromLV(synthetic.peak_boarding_by_hour)}
          />
          <BarChart
            synthetic
            title="Avg passengers per route (weekly)"
            bars={fromLV(synthetic.passengers_per_route_weekly_avg, true)}
          />
        </div>
      </div>
    </section>
  );
}
